index alerts_number: CREATE INDEX alerts_number on alerts (account, number, type)
index alerts_person: CREATE INDEX alerts_person on alerts (account, person, number)
index alerts_type: CREATE INDEX alerts_type on alerts (account, type, number)
index offline_account: CREATE INDEX offline_account on offline(account, id)
index seen_created: CREATE INDEX seen_created on seen(created)
table alerts: CREATE TABLE alerts (id integer primary key autoincrement, account text not null, row text not null, event text not null default '', answer text not null, created integer not null, number integer, type text not null default '', person text, unique (account, row, event))
table filters: CREATE TABLE filters (id integer primary key autoincrement, account text not null, title text not null, context text not null, action text not null default 'warn', keywords text not null default '[]', expires integer not null default 0, created integer not null)
table items: CREATE TABLE items (account text not null, node text not null, item text not null, payload text not null, updated integer not null, primary key (account, node, item))
table joined: CREATE TABLE joined (account text not null, address text not null, room text not null, nick text not null, name text not null default '', seen integer not null default 0, created integer not null, primary key (account, room))
table markers: CREATE TABLE markers (account text not null, timeline text not null, position text not null, version integer not null default 0, updated integer not null, primary key (account, timeline))
table nodes: CREATE TABLE nodes (account text not null, node text not null, access text not null default 'presence', maximum integer not null default 1, created integer not null, primary key (account, node))
table numbers: CREATE TABLE numbers (number integer primary key autoincrement, kind text not null, id text not null, created integer not null, unique (kind, id))
table offline: CREATE TABLE offline (id integer primary key autoincrement, account text not null, stanza text not null, created integer not null)
table pushes: CREATE TABLE pushes (account text not null, service text not null, node text not null, options text not null default '', created integer not null, primary key (account, service, node))
table roster: CREATE TABLE roster (account text not null, address text not null, name text not null default '', subscription text not null default 'none', ask integer not null default 0, pending integer not null default 0, listed integer not null default 0, created integer not null, updated integer not null, primary key (account, address))
table seen: CREATE TABLE seen (id text not null, account text not null, created integer not null, primary key (id, account))
table snapshots: CREATE TABLE snapshots (kind text not null, key text not null, document text not null, created integer not null, updated integer not null, primary key (kind, key))
table snowflakes: CREATE TABLE snowflakes (number integer primary key, kind text not null, key text not null, unique (kind, key))
table subscriptions: CREATE TABLE subscriptions (token text not null primary key, account text not null, endpoint text not null, auth text not null, key text not null, alerts text not null default '{}', policy text not null default 'all', standard integer not null default 0, created integer not null)
